INSERT INTO public.book_questions (id, book_id, chapter_id, page_number, problem_number, question_text) VALUES
  ('class7-agriculture-bn-ch1-p3-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 3, NULL, 'কাজ: দলে আলোচনা করে নিচের প্রশ্ন দুটির উত্তর তৈরি কর এবং শ্রেণিতে উপস্থাপন কর। ১। গুহায় বসবাসকারী নারীরা কীভাবে কৃষিকাজের সূচনা করেছিলেন?'),
  ('class7-agriculture-bn-ch1-p3-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 3, NULL, 'কাজ: দলে আলোচনা করে নিচের প্রশ্ন দুটির উত্তর তৈরি কর এবং শ্রেণিতে উপস্থাপন কর। ২। পরিবার গঠনে কৃষাণি নারী কীভাবে ভূমিকা রেখেছিলেন?'),
  ('class7-agriculture-bn-ch1-p6-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 6, NULL, 'কাজ: নিচের কোন কৃষিজ উপকরণ থেকে কোন দ্রব্যাদি উৎপন্ন হয় তা বাছাই করে খাতায় লেখ। কৃষিজ উপকরণ: ধান, তুলা, পাট, খড়/নাড়া, বাঁশের টুকরা, রসুন, কালোজিরা, নিম, তুলসী, ঘৃতকুমারী (Aloevera)। উৎপন্ন দ্রব্যাদি: চাল, চিড়া, মুড়ি, সুতা, কাপড়, সুতলি, চট, মাথাল, ঘরের মডেল, ট্যাবলেট, তেল, ক্যাপসুল, কাশির ঔষধ, সাবান ও কসমেটিকস।'),
  ('class7-agriculture-bn-ch1-p9-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 9, NULL, 'কাজ: দলীয় আলোচনার মাধ্যমে নিচের ছকটি পূরণ কর ও শ্রেণিতে উপস্থাপন কর। ফসলের নাম: ধান, টমেটো, পাট, গম, আখ, লাউ, ভুট্টা, আম, কাঁঠাল, গাজর। [ছক: মাঠ ফসল | উদ্যান ফসল]'),
  ('class7-agriculture-bn-ch1-p11-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 11, NULL, 'কাজ: দলগত আলোচনার মাধ্যমে আমাদের দেশের কৃষিজ প্রাণীর নামের তালিকা তৈরি কর। তোমাদের এলাকায় কোন কোন প্রাণীর চাষ হয় বা পালন করা হয় সেগুলোর নাম ও গুরুত্ব লেখ।'),
  ('class7-agriculture-bn-ch1-p12-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 12, NULL, 'কাজ: দলীয় আলোচনা কর এবং শ্রেণিতে উপস্থাপন কর। ১। তোমাদের এলাকায় বাংলা নববর্ষ কীভাবে পালন করা হয়?'),
  ('class7-agriculture-bn-ch1-p12-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 12, NULL, 'কাজ: দলীয় আলোচনা কর এবং শ্রেণিতে উপস্থাপন কর। ২। তোমার দেখা একটি গ্রাম্য মেলার বর্ণনা দাও।'),
  ('class7-agriculture-bn-ch1-p13-q1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 13, 1, 'নিচের কোনটি ঔষধি উদ্ভিদ?
ক. ধান
খ. পাট
গ. অ্যালোভেরা
ঘ. বাঁধাকপি'),
  ('class7-agriculture-bn-ch1-p13-q2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 13, 2, 'সামন্তবাদী উৎপাদন ব্যবস্থায়-
i. কৃষিপণ্যের বৈচিত্র্য বেড়েছিল
ii. কৃষিজ উৎপাদন ব্যবস্থার অগ্রগতি হয়েছিল
iii. কৃষিপণ্য বিপণন প্রসারিত হয়েছিল
নিচের কোনটি সঠিক?
ক. i ও ii
খ. ii ও iii
গ. i ও iii
ঘ. i, ii ও iii'),
  ('class7-agriculture-bn-ch1-p13-q3', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 13, 3, 'নিচের অনুচ্ছেদটি পড়ে ৩ ও ৪ নম্বর প্রশ্নের উত্তর দাও। ঝুমার নানা গুঁড়ি গুঁড়ি বৃষ্টির মধ্যে ঝুড়ি ভর্তি রসাল ফলমূল নিয়ে মধু মাসে তাদের বাসায় এলেন। তারা ফলগুলো পেয়ে খুব খুশি হলো। ঝুমার নানা কোন ঋতুতে বেড়াতে আসেন?
ক. গ্রীষ্ম
খ. বর্ষা
গ. শরৎ
ঘ. হেমন্ত'),
  ('class7-agriculture-bn-ch1-p13-q4', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 13, 4, 'নিচের অনুচ্ছেদটি পড়ে ৩ ও ৪ নম্বর প্রশ্নের উত্তর দাও। ঝুমার নানা গুঁড়ি গুঁড়ি বৃষ্টির মধ্যে ঝুড়ি ভর্তি রসাল ফলমূল নিয়ে মধু মাসে তাদের বাসায় এলেন। তারা ফলগুলো পেয়ে খুব খুশি হলো। ঝুমার নানার ফলের ঝুড়িতে ছিল-
i. আম
ii. কমলা
iii. কাঁঠাল
নিচের কোনটি সঠিক?
ক. i ও ii
খ. ii ও iii
গ. i ও iii
ঘ. i, ii ও iii'),
  ('class7-agriculture-bn-ch1-p14-q1ক', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 14, NULL, 'ক্ষুদ্র ব্যবসায়ী রফিক ব্যবসায় লোকসান করে শহর থেকে গ্রামে ফিরে আসেন। ছয় সদস্যের পরিবারের দৈনিক চাহিদা পূরণে রফিকের হিমশিম অবস্থা। গ্রামে কৃষিজ সম্পদের মধ্যে তাঁর ছোট একটি বসতবাড়ি ছাড়া মাঝারি একটি পুকুর ও ৫০ শতাংশ ফসলি জমি আছে। এ অবস্থায় চাচা আলতাফ মাস্টারের পরামর্শমতো তিনি তার একটি কৃষিজ সম্পদ ব্যবহারের উদ্যোগ নেন। এতে তিনি পরিবারের দৈনন্দিন প্রাণিজ আমিষের চাহিদা পূরণের পাশাপাশি বাণিজ্যিকভাবেও লাভবান হন। পরবর্তী সময়ে তিনি তাঁর অন্যান্য কৃষিজ সম্পদ ব্যবহারেরও উদ্যোগ গ্রহণ করেন। ক. কৃষিকে পেশা হিসেবে নেওয়ার আগে মানুষ কয়টি উপায়ে খাদ্য সংগ্রহ করত?'),
  ('class7-agriculture-bn-ch1-p14-q1খ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 14, NULL, 'ক্ষুদ্র ব্যবসায়ী রফিক ব্যবসায় লোকসান করে শহর থেকে গ্রামে ফিরে আসেন। ছয় সদস্যের পরিবারের দৈনিক চাহিদা পূরণে রফিকের হিমশিম অবস্থা। গ্রামে কৃষিজ সম্পদের মধ্যে তাঁর ছোট একটি বসতবাড়ি ছাড়া মাঝারি একটি পুকুর ও ৫০ শতাংশ ফসলি জমি আছে। এ অবস্থায় চাচা আলতাফ মাস্টারের পরামর্শমতো তিনি তার একটি কৃষিজ সম্পদ ব্যবহারের উদ্যোগ নেন। এতে তিনি পরিবারের দৈনন্দিন প্রাণিজ আমিষের চাহিদা পূরণের পাশাপাশি বাণিজ্যিকভাবেও লাভবান হন। পরবর্তী সময়ে তিনি তাঁর অন্যান্য কৃষিজ সম্পদ ব্যবহারেরও উদ্যোগ গ্রহণ করেন। খ. কলাকে ঋতু নিরপেক্ষ ফল বলার কারণ ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch1-p14-q1গ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 14, NULL, 'ক্ষুদ্র ব্যবসায়ী রফিক ব্যবসায় লোকসান করে শহর থেকে গ্রামে ফিরে আসেন। ছয় সদস্যের পরিবারের দৈনিক চাহিদা পূরণে রফিকের হিমশিম অবস্থা। গ্রামে কৃষিজ সম্পদের মধ্যে তাঁর ছোট একটি বসতবাড়ি ছাড়া মাঝারি একটি পুকুর ও ৫০ শতাংশ ফসলি জমি আছে। এ অবস্থায় চাচা আলতাফ মাস্টারের পরামর্শমতো তিনি তার একটি কৃষিজ সম্পদ ব্যবহারের উদ্যোগ নেন। এতে তিনি পরিবারের দৈনন্দিন প্রাণিজ আমিষের চাহিদা পূরণের পাশাপাশি বাণিজ্যিকভাবেও লাভবান হন। পরবর্তী সময়ে তিনি তাঁর অন্যান্য কৃষিজ সম্পদ ব্যবহারেরও উদ্যোগ গ্রহণ করেন। গ. রফিক যে উপায়ে তাঁর কৃষিজ সম্পদ ব্যবহার করে লাভবান হয়েছিলেন তা বর্ণনা কর।'),
  ('class7-agriculture-bn-ch1-p14-q1ঘ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 14, NULL, 'ক্ষুদ্র ব্যবসায়ী রফিক ব্যবসায় লোকসান করে শহর থেকে গ্রামে ফিরে আসেন। ছয় সদস্যের পরিবারের দৈনিক চাহিদা পূরণে রফিকের হিমশিম অবস্থা। গ্রামে কৃষিজ সম্পদের মধ্যে তাঁর ছোট একটি বসতবাড়ি ছাড়া মাঝারি একটি পুকুর ও ৫০ শতাংশ ফসলি জমি আছে। এ অবস্থায় চাচা আলতাফ মাস্টারের পরামর্শমতো তিনি তার একটি কৃষিজ সম্পদ ব্যবহারের উদ্যোগ নেন। এতে তিনি পরিবারের দৈনন্দিন প্রাণিজ আমিষের চাহিদা পূরণের পাশাপাশি বাণিজ্যিকভাবেও লাভবান হন। পরবর্তী সময়ে তিনি তাঁর অন্যান্য কৃষিজ সম্পদ ব্যবহারেরও উদ্যোগ গ্রহণ করেন। ঘ. রফিক কৃষিজ সম্পদ ব্যবহারের যে উদ্যোগগুলো গ্রহণ করেন তা আমাদের খাদ্য চাহিদার প্রেক্ষাপটে মূল্যায়ন কর।'),
  ('class7-agriculture-bn-ch1-p14-q2ক', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 14, NULL, 'রহিম মিয়া তাঁর জমিতে বিভিন্ন প্রকার মাঠ ফসল ও উদ্যান ফসলের চাষ করেছেন। নতুন ধান উঠায় তার পরিবারসহ সবাই নবান্ন উৎসবে মেতে উঠল। ক. মানুষ কখন আগুনের ব্যবহার ও নিয়ন্ত্রণ শিখেছিল?'),
  ('class7-agriculture-bn-ch1-p14-q2খ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 14, NULL, 'রহিম মিয়া তাঁর জমিতে বিভিন্ন প্রকার মাঠ ফসল ও উদ্যান ফসলের চাষ করেছেন। নতুন ধান উঠায় তার পরিবারসহ সবাই নবান্ন উৎসবে মেতে উঠল। খ. পরিবারের বৈশিষ্ট্যগুলো লেখ।'),
  ('class7-agriculture-bn-ch1-p15-q1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 15, 1, 'উদ্যান ফসল কী? ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch1-p15-q2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 15, 2, 'নবান্ন উৎসব কাকে বলে? কখন হয়?'),
  ('class7-agriculture-bn-ch1-p15-q2গ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 15, NULL, 'রহিম মিয়া তাঁর জমিতে বিভিন্ন প্রকার মাঠ ফসল ও উদ্যান ফসলের চাষ করেছেন। নতুন ধান উঠায় তার পরিবারসহ সবাই নবান্ন উৎসবে মেতে উঠল। গ. রহিম মিয়ার কার্যক্রম কীভাবে খাদ্য চাহিদা মেটাতে সাহায্য করে? ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch1-p15-q2ঘ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 15, NULL, 'রহিম মিয়া তাঁর জমিতে বিভিন্ন প্রকার মাঠ ফসল ও উদ্যান ফসলের চাষ করেছেন। নতুন ধান উঠায় তার পরিবারসহ সবাই নবান্ন উৎসবে মেতে উঠল। ঘ. উল্লিখিত উৎসবের সাথে রহিম মিয়ার কৃষিকাজের সঙ্গতিপূর্ণতা বিশ্লেষণ কর।'),
  ('class7-agriculture-bn-ch1-p15-q3', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 15, 3, 'কৃষি ঋতু কয়টি ও কি কি?'),
  ('class7-agriculture-bn-ch1-p15-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 15, NULL, 'অ্যাসাইনমেন্ট: মানব সমাজ বিবর্তনে কৃষি কী ভূমিকা রেখেছে তার একটি বর্ণনা লিখে শিক্ষকের নিকট জমা দাও।'),
  ('class7-agriculture-bn-ch1-p15-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch1', 15, NULL, 'অনুসন্ধানমূলক কাজ: বিভিন্ন প্রকারের মাঠ ও উদ্যান ফসলের বীজের নমুনা সংগ্রহ করা।'),
  ('class7-agriculture-bn-ch2-p18-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 18, NULL, 'কাজ: তোমরা গ্রামের ফসলের মাঠ ঘুরে দেখ কীভাবে সেচের পানির অপচয় হচ্ছে। আর কৃষকেরা অপচয় রোধের জন্য কী ব্যবস্থা নিচ্ছেন। এ বিষয়ের উপর একটি প্রতিবেদন লিখে উপস্থাপন কর।'),
  ('class7-agriculture-bn-ch2-p21-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 21, NULL, 'কাজ: ফসল বা সবজির মাঠ পরিদর্শনে যাও এবং দেখ কীভাবে কৃষকেরা সেচ দিচ্ছেন। ব্যবহৃত সেচ পদ্ধতির উপর প্রতিবেদন তৈরি করে শ্রেণিতে উপস্থাপন কর।'),
  ('class7-agriculture-bn-ch2-p22-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 22, NULL, 'কাজ: পেঁপে বাগানে জমে থাকা বৃষ্টির পানি দ্রুত নিষ্কাশনের উপযুক্ত পদ্ধতি সম্পর্কে দলগত আলোচনা করে শ্রেণিতে উপস্থাপন কর।'),
  ('class7-agriculture-bn-ch2-p24-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 24, NULL, 'কাজ: গ্রামের পুকুরগুলো ঘুরে দেখ। আর দেখ কীভাবে পুকুরের পানি দূষিত হচ্ছে। দূষিত পুকুরের মাছগুলো বাঁচাবার জন্য কৃষকেরা কী ব্যবস্থা নিচ্ছেন তা দেখ এবং লেখ।'),
  ('class7-agriculture-bn-ch2-p28-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 28, NULL, 'কাজ: তোমার বাড়ির পাশে ৩ মিটার × ১ মিটারের একটি জায়গা নির্বাচন কর। ১। বীজতলায় চারা উৎপাদন কর। ২। কোদাল দিয়ে নির্বাচিত স্থানের মাটি ঝুরঝুরা করে চাষ কর। ৩। বীজতলা মাটি থেকে কমপক্ষে ১০ সেমি উঁচুতে হতে হবে। ৪। পচা গোবরের সাথে ১০ গ্রাম ইউরিয়া মিশিয়ে বীজতলার উপর ছিটিয়ে দাও এবং মিশিয়ে দাও। মাটির ২ সেমি গভীরে বীজ বপন কর। ৫। প্রতিদিন বীজতলায় ঝাঁঝরি দিয়ে পানি দাও। ৩–৪ দিনের মধ্যেই চারা বের হবে। ৬। যতদিন চারা মূল জমিতে রোপণের উপযুক্ত না হবে ততদিন এই পাঠের নির্দেশমতো বীজতলার যত্ন নাও।'),
  ('class7-agriculture-bn-ch2-p30-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 30, NULL, 'কাজ: ১। গোলাপের একটি ডাল কেটে ছেদ কলম তৈরির মাধ্যমে চারা তৈরি কর।'),
  ('class7-agriculture-bn-ch2-p30-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 30, NULL, 'কাজ: ২। গুটি কলম পদ্ধতিতে রঙ্গনের একটি চারা তৈরি করে টবে রোপণ কর।'),
  ('class7-agriculture-bn-ch2-p33-q1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 33, 1, 'বাচ্চা ফোটানোর জন্য নির্বাচিত ডিম শীতকালে কতদিন পর্যন্ত সংরক্ষণ করা যাবে?
ক. ৩–৪ দিন
খ. ৪–৫ দিন
গ. ৭–১০ দিন
ঘ. ১০–১২ দিন'),
  ('class7-agriculture-bn-ch2-p33-q2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 33, 2, 'ফোয়ারা পদ্ধতিতে সেচ দেওয়া হয়-
i. বীজতলায়
ii. শাক-সবজির ক্ষেতে
iii. বহুবর্ষজীবী ফল গাছে
নিচের কোনটি সঠিক?
ক. i
খ. ii
গ. i ও ii
ঘ. ii ও iii'),
  ('class7-agriculture-bn-ch2-p33-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 33, NULL, 'কাজ: শিক্ষক শিক্ষার্থীদেরকে নিয়ে আশেপাশের কোনো মুরগির খামার পরিদর্শন করবেন এবং পরিদর্শন শেষে শিক্ষার্থীরা দলীয়ভাবে একটি প্রতিবেদন তৈরি করে জমা দিবে।'),
  ('class7-agriculture-bn-ch2-p34-q3', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 34, 3, 'নিচের অনুচ্ছেদটি পড়ে ৩ ও ৪ নম্বর প্রশ্নের উত্তর দাও। রাজিয়ার বাবা তাঁর ৫ শতকের একটি পরিত্যক্ত পুকুরে মাছ চাষের উদ্যোগ নেন এবং চাষ শুরু করেন। কিন্তু কিছুদিন যাবৎ রাজিয়া লক্ষ করে যে, পুকুরের পানি ঘন সবুজ রং ধারণ করেছে এবং মাঝে মাঝে মৃত মাছও ভেসে উঠে। ৭ম শ্রেণির শিক্ষার্থী রাজিয়া তার বাবাকে এ সমস্যা সমাধানে পুকুরে চুনে বা কপার সালফেট প্রয়োগের পরামর্শ দেয়। রাজিয়ার বাবার পুকুরের জন্য প্রয়োজনীয় চুনে বা কপার সালফেটের পরিমাণ কত?
ক. ১২–১৫ গ্রাম
খ. ২৪–৩০ গ্রাম
গ. ৪৮–৬০ গ্রাম
ঘ. ৬০–৭৫ গ্রাম'),
  ('class7-agriculture-bn-ch2-p34-q4', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 34, 4, 'নিচের অনুচ্ছেদটি পড়ে ৩ ও ৪ নম্বর প্রশ্নের উত্তর দাও। রাজিয়ার বাবা তাঁর ৫ শতকের একটি পরিত্যক্ত পুকুরে মাছ চাষের উদ্যোগ নেন এবং চাষ শুরু করেন। কিন্তু কিছুদিন যাবৎ রাজিয়া লক্ষ করে যে, পুকুরের পানি ঘন সবুজ রং ধারণ করেছে এবং মাঝে মাঝে মৃত মাছও ভেসে উঠে। ৭ম শ্রেণির শিক্ষার্থী রাজিয়া তার বাবাকে এ সমস্যা সমাধানে পুকুরে চুনে বা কপার সালফেট প্রয়োগের পরামর্শ দেয়। রাজিয়ার বাবার পুকুরে উদ্ভূত সমস্যার কারণ কী?
ক. পুকুরে শেওলার স্তর সৃষ্টি হওয়া
খ. পুকুরের পানি ঘোলা হওয়া
গ. পুকুরে অতিরিক্ত চুন দেওয়া
ঘ. পুকুরের পানির অম্লত্ব ও ক্ষারত্ব কম-বেশি হওয়া'),
  ('class7-agriculture-bn-ch2-p35-q1ক', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 35, NULL, '[চিত্র: ক — একটি গাছের নিচু ডাল মাটিতে নুইয়ে মাটির নিচে চাপা দিয়ে নতুন চারা গজানো; খ — তিনটি কাটা ডালের টুকরো মাটিতে খাড়া ও হেলানোভাবে পোঁতা, ডানদিকেরটিতে নতুন পাতা ও কুঁড়ি গজিয়েছে] ক. উদ্ভিদের অঙ্গজ বংশবিস্তার বলতে কী বোঝ?'),
  ('class7-agriculture-bn-ch2-p35-q1খ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 35, NULL, '[চিত্র: ক — একটি গাছের নিচু ডাল মাটিতে নুইয়ে মাটির নিচে চাপা দিয়ে নতুন চারা গজানো; খ — তিনটি কাটা ডালের টুকরো মাটিতে খাড়া ও হেলানোভাবে পোঁতা, ডানদিকেরটিতে নতুন পাতা ও কুঁড়ি গজিয়েছে] খ. অঙ্গজ বংশবিস্তারের একটি সুবিধা ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch2-p35-q1গ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 35, NULL, '[চিত্র: ক — একটি গাছের নিচু ডাল মাটিতে নুইয়ে মাটির নিচে চাপা দিয়ে নতুন চারা গজানো; খ — তিনটি কাটা ডালের টুকরো মাটিতে খাড়া ও হেলানোভাবে পোঁতা, ডানদিকেরটিতে নতুন পাতা ও কুঁড়ি গজিয়েছে] গ. গোলাপের বংশবিস্তারের ক্ষেত্রে ক ও খ চিত্রে প্রদর্শিত পদ্ধতি দুইটির মধ্যে কোনটি কার্যকরী? কারণ ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch2-p35-q1ঘ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 35, NULL, '[চিত্র: ক — একটি গাছের নিচু ডাল মাটিতে নুইয়ে মাটির নিচে চাপা দিয়ে নতুন চারা গজানো; খ — তিনটি কাটা ডালের টুকরো মাটিতে খাড়া ও হেলানোভাবে পোঁতা, ডানদিকেরটিতে নতুন পাতা ও কুঁড়ি গজিয়েছে] ঘ. চিত্রের পদ্ধতিসমূহ ভালো ফলনে কীভাবে ভূমিকা রাখতে পারে? বিশ্লেষণ কর।'),
  ('class7-agriculture-bn-ch2-p35-q2ক', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 35, NULL, 'তানভির আহমেদ তাঁর পারিবারিক চাহিদা মেটানোর জন্য বাড়ির পাশের স্বল্প জমিতে টমেটো ও ফুলকপি চাষ শুরু করেন। এ ছাড়া বাড়ির পিছনে তাঁর ৫ বছরের পুরানো আমের একটি বাগানও আছে। তানভির আহমেদ আম বাগানে যে সেচ পদ্ধতিটি অনুসরণ করে সফলতা লাভ করেন তা তাঁর সবজি ক্ষেত্রে প্রয়োগ করেন। এতে সবজি বাগানে সমস্যা দেখা দেয়। ক. পানি সেচ কেন দেওয়া হয়?'),
  ('class7-agriculture-bn-ch2-p35-q2খ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 35, NULL, 'তানভির আহমেদ তাঁর পারিবারিক চাহিদা মেটানোর জন্য বাড়ির পাশের স্বল্প জমিতে টমেটো ও ফুলকপি চাষ শুরু করেন। এ ছাড়া বাড়ির পিছনে তাঁর ৫ বছরের পুরানো আমের একটি বাগানও আছে। তানভির আহমেদ আম বাগানে যে সেচ পদ্ধতিটি অনুসরণ করে সফলতা লাভ করেন তা তাঁর সবজি ক্ষেত্রে প্রয়োগ করেন। এতে সবজি বাগানে সমস্যা দেখা দেয়। খ. সেচের পানির কার্যকারিতা বৃদ্ধির একটি প্রযুক্তি ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch2-p36-q1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 36, 1, 'ছেদ কলম কী? কর্তন বা ছেদ কলম কীভাবে করা হয়?'),
  ('class7-agriculture-bn-ch2-p36-q2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 36, 2, 'পানি শোধন কী? পুকুরের পানি কেন শোধন করা হয়?'),
  ('class7-agriculture-bn-ch2-p36-q2গ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 36, NULL, 'তানভির আহমেদ তাঁর পারিবারিক চাহিদা মেটানোর জন্য বাড়ির পাশের স্বল্প জমিতে টমেটো ও ফুলকপি চাষ শুরু করেন। এ ছাড়া বাড়ির পিছনে তাঁর ৫ বছরের পুরানো আমের একটি বাগানও আছে। তানভির আহমেদ আম বাগানে যে সেচ পদ্ধতিটি অনুসরণ করে সফলতা লাভ করেন তা তাঁর সবজি ক্ষেত্রে প্রয়োগ করেন। এতে সবজি বাগানে সমস্যা দেখা দেয়। গ. তানভির আহমেদ যে সেচ পদ্ধতি প্রয়োগ করে চাষে সফলতা পান তা ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch2-p36-q2ঘ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 36, NULL, 'তানভির আহমেদ তাঁর পারিবারিক চাহিদা মেটানোর জন্য বাড়ির পাশের স্বল্প জমিতে টমেটো ও ফুলকপি চাষ শুরু করেন। এ ছাড়া বাড়ির পিছনে তাঁর ৫ বছরের পুরানো আমের একটি বাগানও আছে। তানভির আহমেদ আম বাগানে যে সেচ পদ্ধতিটি অনুসরণ করে সফলতা লাভ করেন তা তাঁর সবজি ক্ষেত্রে প্রয়োগ করেন। এতে সবজি বাগানে সমস্যা দেখা দেয়। ঘ. তানভির আহমেদ কীভাবে সবজি ক্ষেত্রে উদ্ভূত সমস্যার সমাধান করবেন বিশ্লেষণ কর।'),
  ('class7-agriculture-bn-ch2-p36-q3', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 36, 3, 'সেটিং ট্রেতে কী বসানো হয় এবং কীভাবে বসানো হয়?'),
  ('class7-agriculture-bn-ch2-p36-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch2', 36, NULL, 'অ্যাসাইনমেন্ট: শিক্ষার্থীরা ফসলের মাঠ পরিদর্শন করে কৃষকেরা কীভাবে জমির অতিরিক্ত পানি নিকাশ করছে তা পর্যবেক্ষণ করবে। পরিদর্শন শেষে দলীয়ভাবে প্রতিবেদন তৈরি করে শিক্ষকের নিকট জমা দিবে।'),
  ('class7-agriculture-bn-ch3-p39-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 39, NULL, 'কাজ: শিক্ষক শিক্ষার্থীদের কয়েকটি দলে বিভক্ত করে প্রতিটি দলে ইউরিয়া, টিএসপি, এমওপি, জিপসাম সারের নমুনা দিবেন। এ সারগুলো প্রধানত কোন কোন পুষ্টি উপাদান সরবরাহ করে তাদের নাম ও ৩টি করে কাজ লিখিয়ে দলীয়ভাবে উপস্থাপন করাবেন।'),
  ('class7-agriculture-bn-ch3-p40-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 40, NULL, 'কাজ: শিক্ষক শিক্ষার্থীদের দ্বারা নাইট্রোজেন, ফসফরাস, সালফার ও ক্যালসিয়াম নামে দল গঠন করবেন। প্রত্যেক দলকে নিজ নিজ দলের পুষ্টি উপাদানের কাজ ও তাদেরকে যে যে সারে পাওয়া যায় তার একটি তালিকা তৈরি করতে বলবেন। এ ক্ষেত্রে শিক্ষার্থীরা শ্রেণিকক্ষে শিক্ষকের দেখানো নমুনা সার/নমুনা উদ্ভিদ প্রদর্শন করে দলীয় কাজটি করতে পারে।'),
  ('class7-agriculture-bn-ch3-p41-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 41, NULL, 'কাজ: শিক্ষক নাইট্রোজেন, ফসফরাস, পটাশিয়াম ও জিংকের অভাবে উদ্ভিদে বা ফসলে কী কী লক্ষণ প্রকাশ পায় তার নমুনা স্থিরচিত্র বা ভিডিও প্রদর্শনের মাধ্যমে দেখাবেন। শিক্ষার্থীরা উক্ত পুষ্টি উপাদানের অভাবে কোন কোন নমুনায় প্রকাশ পেয়েছে এবং লক্ষণগুলো কী কী তা দলীয়ভাবে লিখে শ্রেণিতে উপস্থাপন করবে।'),
  ('class7-agriculture-bn-ch3-p43-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 43, NULL, 'কাজ: অপুষ্টিতে ভুগছে এমন গৃহপালিত পশু এবং সঠিক পুষ্টিসম্পন্ন সুস্থ গৃহপালিত পশুর স্থিরচিত্র বা ভিডিও শিক্ষক শ্রেণিকক্ষে দেখাবেন এবং শিক্ষার্থীদেরকে এ দুই ধরনের গৃহপালিত পশুর শারীরিক গঠন ও সুস্থতার পার্থক্যের কারণ ব্যাখ্যা করতে বলবেন। এ কাজটি উক্ত আলোচনা বা দলীয়ভাবে শিক্ষক করাতে পারবেন।'),
  ('class7-agriculture-bn-ch3-p46-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 46, NULL, 'কাজ: শিক্ষক শিক্ষার্থীদেরকে দলীয়ভাবে চিংড়ি চাষের জন্য ১০ কেজি সম্পূরক খাদ্যের ১টি তালিকা পোস্টার পেপারে লিপিবদ্ধ করতে বলবেন।'),
  ('class7-agriculture-bn-ch3-p46-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 46, NULL, 'কাজ: শিক্ষক শিক্ষার্থীদেরকে দলীয়ভাবে ২ কেজি দানাদার খাদ্য তৈরি করার কৌশল পোস্টার পেপারে উপস্থাপন করতে বলবেন।'),
  ('class7-agriculture-bn-ch3-p47-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 47, NULL, 'কাজ: শিক্ষক শিক্ষার্থীদেরকে দলীয়ভাবে বাড়ন্ত মুরগির জন্য ১ কেজি সম্পূরক খাদ্য তৈরি, খাদ্য উপকরণ ও পরিমাণসহ একটি পোস্টার তৈরি করতে বলবেন।'),
  ('class7-agriculture-bn-ch3-p47-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 47, NULL, 'কাজ: শিক্ষক শিক্ষার্থীদের কয়েকটি দলে বিভক্ত করে ‘জৈব সার ব্যবহারের উপকারিতা’ বিষয়ে শ্রেণিতে লিখতে দিবেন এবং দলগতভাবে তা উপস্থাপন করার ব্যবস্থা করবেন।'),
  ('class7-agriculture-bn-ch3-p50-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 50, NULL, 'কাজ-১: শিক্ষক শ্রেণিকক্ষে কিছু পরিমাণ কম্পোস্ট সার নিয়ে আসবেন। শিক্ষার্থীদের কয়েকটি দলে ভাগ করে উক্ত সারগুলো শিক্ষা প্রতিষ্ঠানের বাগান বা টবে তাদের দ্বারা প্রয়োগ করার ব্যবস্থা করবেন। এক্ষেত্রে শিক্ষক প্রয়োগের নিয়মাবলি শিখিয়ে দিবেন।'),
  ('class7-agriculture-bn-ch3-p50-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 50, NULL, 'কাজ-২: শিক্ষক শিক্ষার্থীদের কয়েকটি দলে বিভক্ত করে পরিখা পদ্ধতিতে কম্পোস্ট তৈরির চিহ্নিত চিত্র ও কম্পোস্ট সারের ব্যবহার সম্পর্কিত একটি পোস্টার তৈরি করতে বলবেন। শিক্ষক সেগুলো মূল্যায়ন করবেন।'),
  ('class7-agriculture-bn-ch3-p51-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 51, NULL, 'কাজ: শিক্ষক শিক্ষার্থীদেরকে দলীয়ভাবে রাসায়নিক ও অরাসায়নিক বালাইনাশকের সুবিধা ও অসুবিধাগুলো লিখতে বলবেন।'),
  ('class7-agriculture-bn-ch3-p52-q1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 52, 1, 'উদ্ভিদের পুষ্টি উপাদান কয়টি?
ক. ১১
খ. ১৪
গ. ১৭
ঘ. ২০'),
  ('class7-agriculture-bn-ch3-p52-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 52, NULL, 'কাজ-১: সম্ভব হলে শিক্ষক কীটপতঙ্গ দমনে খাদক পোকামাকড় ব্যবহার, হরমোন ফাঁদ, আলোর ফাঁদ ও রাসায়নিক বালাইনাশকের ব্যবহার ভিডিও/ছবি/পোস্টার নমুনার সাহায্যে দেখাবেন।'),
  ('class7-agriculture-bn-ch3-p52-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 52, NULL, 'কাজ-২: শিক্ষক শিক্ষার্থীদের এককভাবে ''রাসায়নিক বালাইনাশক ব্যবহারের কুফল'' বিষয়ে পোস্টার পেপার অঙ্কন করতে বলবেন অথবা লিখতে বলবেন।'),
  ('class7-agriculture-bn-ch3-p52-t3', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 52, NULL, 'অথবা — কাজ-১: শিক্ষক শিক্ষার্থীদের অপকারী বা ক্ষতিকর পোকাখাদক পাখি ও পোকার নামের একটি তালিকা তৈরি করতে বলবেন। এ কাজটি শিক্ষক দলীয়ভাবে সম্পন্ন করার ব্যবস্থা করবেন।'),
  ('class7-agriculture-bn-ch3-p52-t4', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 52, NULL, 'অথবা — কাজ-২: শিক্ষক শিক্ষার্থীদের কয়েকটি দলে বিভক্ত করে জৈব ও অরাসায়নিক বালাইনাশক সংগ্রহ করে জমা দিতে বলবেন।'),
  ('class7-agriculture-bn-ch3-p53-q2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 53, 2, 'উদ্ভিদে কার্বন ও হাইড্রোজেন ঘাটতি পূরণে প্রয়োজন-
i. পানি
ii. মাটি
iii. বায়ু
নিচের কোনটি সঠিক?
ক. i ও ii
খ. i ও iii
গ. ii ও iii
ঘ. i, ii ও iii'),
  ('class7-agriculture-bn-ch3-p53-q3', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 53, 3, 'নিচের অনুচ্ছেদটি পড়ে ৩ ও ৪ নম্বর প্রশ্নের উত্তর দাও। সালমা নতুন মুরগি চাষি, সে ডিম উৎপাদনের জন্য বাজার থেকে ১৮ টি মুরগি ও ৬ কেজি মুরগির খাদ্য কিনে আনে। কিন্তু দু''দিন পর সে লক্ষ করল মুরগির ডিমের খোসাগুলো বেশ নরম প্রকৃতির, ফলে সে বিচলিত হয়ে পড়ে। ন্যূনতম হারে খাদ্য খাওয়ালে সালমা ক্রয়কৃত খাদ্য মুরগিগুলোকে কয়দিন খাওয়াতে পারবে?
ক. ১
খ. ২
গ. ৩
ঘ. ৪'),
  ('class7-agriculture-bn-ch3-p53-q4', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 53, 4, 'নিচের অনুচ্ছেদটি পড়ে ৩ ও ৪ নম্বর প্রশ্নের উত্তর দাও। সালমা নতুন মুরগি চাষি, সে ডিম উৎপাদনের জন্য বাজার থেকে ১৮ টি মুরগি ও ৬ কেজি মুরগির খাদ্য কিনে আনে। কিন্তু দু''দিন পর সে লক্ষ করল মুরগির ডিমের খোসাগুলো বেশ নরম প্রকৃতির, ফলে সে বিচলিত হয়ে পড়ে। সালমার মুরগির ডিম উৎপাদনে সৃষ্ট সমস্যা সমাধানের জন্য খাদ্যে যোগ করতে হবে-
ক. খৈল
খ. ডাল চূর্ণ
গ. ভুট্টা ভাঙা
ঘ. লবণ'),
  ('class7-agriculture-bn-ch3-p54-q1ক', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 54, NULL, 'সরদারপাড়া গ্রামের কৃষক হাফিজ ২০ শতাংশ জমি বর্গা নিয়ে ধান চাষ শুরু করে লক্ষ করলেন ধান চারার কুশি আশানুরূপ হারে গজাচ্ছে না এবং জমিতে পোকামাকড় দেখা যাচ্ছে। চিন্তিত হাফিজকে বিভিন্নজন রাসায়নিক সার ও কীটনাশক প্রয়োগের পরামর্শ দিলেও তিনি সেটি গ্রহণ করেননি। ফলে প্রথম দফায় সে সফল না হলেও পরের বছর জৈব ব্যবস্থাপনা গ্রহণ করে তিনি ঐ জমি থেকে কাঙ্ক্ষিত ফল অর্জন করেন। ক. উদ্ভিদের পুষ্টি উপাদান বলতে কী বোঝ?'),
  ('class7-agriculture-bn-ch3-p54-q1খ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 54, NULL, 'সরদারপাড়া গ্রামের কৃষক হাফিজ ২০ শতাংশ জমি বর্গা নিয়ে ধান চাষ শুরু করে লক্ষ করলেন ধান চারার কুশি আশানুরূপ হারে গজাচ্ছে না এবং জমিতে পোকামাকড় দেখা যাচ্ছে। চিন্তিত হাফিজকে বিভিন্নজন রাসায়নিক সার ও কীটনাশক প্রয়োগের পরামর্শ দিলেও তিনি সেটি গ্রহণ করেননি। ফলে প্রথম দফায় সে সফল না হলেও পরের বছর জৈব ব্যবস্থাপনা গ্রহণ করে তিনি ঐ জমি থেকে কাঙ্ক্ষিত ফল অর্জন করেন। খ. পরিখা পদ্ধতিতে কম্পোস্ট তৈরির ক্ষেত্রে একটি পরিখা ফাঁকা রাখার প্রয়োজনীয়তা ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch3-p54-q1গ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 54, NULL, 'সরদারপাড়া গ্রামের কৃষক হাফিজ ২০ শতাংশ জমি বর্গা নিয়ে ধান চাষ শুরু করে লক্ষ করলেন ধান চারার কুশি আশানুরূপ হারে গজাচ্ছে না এবং জমিতে পোকামাকড় দেখা যাচ্ছে। চিন্তিত হাফিজকে বিভিন্নজন রাসায়নিক সার ও কীটনাশক প্রয়োগের পরামর্শ দিলেও তিনি সেটি গ্রহণ করেননি। ফলে প্রথম দফায় সে সফল না হলেও পরের বছর জৈব ব্যবস্থাপনা গ্রহণ করে তিনি ঐ জমি থেকে কাঙ্ক্ষিত ফল অর্জন করেন। গ. প্রথম দফায় কী ধরনের জৈব ব্যবস্থাপনা গ্রহণ করলে হাফিজ উদ্ভূত পরিস্থিতি মোকাবেলা করতে পারতেন তা বর্ণনা কর।'),
  ('class7-agriculture-bn-ch3-p54-q1ঘ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 54, NULL, 'সরদারপাড়া গ্রামের কৃষক হাফিজ ২০ শতাংশ জমি বর্গা নিয়ে ধান চাষ শুরু করে লক্ষ করলেন ধান চারার কুশি আশানুরূপ হারে গজাচ্ছে না এবং জমিতে পোকামাকড় দেখা যাচ্ছে। চিন্তিত হাফিজকে বিভিন্নজন রাসায়নিক সার ও কীটনাশক প্রয়োগের পরামর্শ দিলেও তিনি সেটি গ্রহণ করেননি। ফলে প্রথম দফায় সে সফল না হলেও পরের বছর জৈব ব্যবস্থাপনা গ্রহণ করে তিনি ঐ জমি থেকে কাঙ্ক্ষিত ফল অর্জন করেন। ঘ. হাফিজের দ্বিতীয় বারের চাষ ব্যবস্থাপনা শুধু পুষ্টি ঘাটতি পূরণই নয় রোগবালাই দমনেও সহায়ক ভূমিকা রেখেছে— মূল্যায়ন কর।'),
  ('class7-agriculture-bn-ch3-p55-q1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, 1, 'উদ্ভিদের পুষ্টি উপাদানের উৎস কয়টি ও কী কী?'),
  ('class7-agriculture-bn-ch3-p55-q2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, 2, 'সম্পূরক খাদ্য বলতে কী বোঝ? এ খাদ্য কেন প্রয়োজন?'),
  ('class7-agriculture-bn-ch3-p55-q2ক', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, NULL, 'মনিরা বেগম দ্বিতীয় বারের মতো বাড়ির পাশের পতিত জমিটি চাষের জন্য ঠিক করে বেগুনের চারা রোপণ করলেন। চারাগুলো বড় হলে ফুল ও ফল আসে। কিন্তু এক সময় জমির অধিকাংশ বেগুন গাছের কাণ্ডে ও ডগায় বিভিন্ন রকমের পোকার উপস্থিতি দেখা যায় আর কিছু কিছু বেগুনে ছোট কালো ছিদ্র লক্ষ করা যায়। গত বছর এই একই পরিস্থিতিতে তিনি কীটনাশক প্রয়োগ করেছিলেন কিন্তু কোনো উপকার পাননি বরং অর্থের অপচয় হয়েছে। তাই এবার তিনি বিকল্প উপায় খুঁজতে কৃষি কর্মকর্তার সঙ্গে পরামর্শ করেন। ক. পরিবেশকে বাঁচাতে কী ধরনের বালাইনাশক ব্যবহার করতে হয়?'),
  ('class7-agriculture-bn-ch3-p55-q2খ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, NULL, 'মনিরা বেগম দ্বিতীয় বারের মতো বাড়ির পাশের পতিত জমিটি চাষের জন্য ঠিক করে বেগুনের চারা রোপণ করলেন। চারাগুলো বড় হলে ফুল ও ফল আসে। কিন্তু এক সময় জমির অধিকাংশ বেগুন গাছের কাণ্ডে ও ডগায় বিভিন্ন রকমের পোকার উপস্থিতি দেখা যায় আর কিছু কিছু বেগুনে ছোট কালো ছিদ্র লক্ষ করা যায়। গত বছর এই একই পরিস্থিতিতে তিনি কীটনাশক প্রয়োগ করেছিলেন কিন্তু কোনো উপকার পাননি বরং অর্থের অপচয় হয়েছে। তাই এবার তিনি বিকল্প উপায় খুঁজতে কৃষি কর্মকর্তার সঙ্গে পরামর্শ করেন। খ. কী কারণে বালাইনাশককে নীরব ঘাতক বলা হয় ব্যাখ্যা কর।'),
  ('class7-agriculture-bn-ch3-p55-q2গ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, NULL, 'মনিরা বেগম দ্বিতীয় বারের মতো বাড়ির পাশের পতিত জমিটি চাষের জন্য ঠিক করে বেগুনের চারা রোপণ করলেন। চারাগুলো বড় হলে ফুল ও ফল আসে। কিন্তু এক সময় জমির অধিকাংশ বেগুন গাছের কাণ্ডে ও ডগায় বিভিন্ন রকমের পোকার উপস্থিতি দেখা যায় আর কিছু কিছু বেগুনে ছোট কালো ছিদ্র লক্ষ করা যায়। গত বছর এই একই পরিস্থিতিতে তিনি কীটনাশক প্রয়োগ করেছিলেন কিন্তু কোনো উপকার পাননি বরং অর্থের অপচয় হয়েছে। তাই এবার তিনি বিকল্প উপায় খুঁজতে কৃষি কর্মকর্তার সঙ্গে পরামর্শ করেন। গ. মনিরা বেগমের সবজি ক্ষেত্রের সমস্যা দূরীকরণের উপায় বর্ণনা কর।'),
  ('class7-agriculture-bn-ch3-p55-q2ঘ', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, NULL, 'মনিরা বেগম দ্বিতীয় বারের মতো বাড়ির পাশের পতিত জমিটি চাষের জন্য ঠিক করে বেগুনের চারা রোপণ করলেন। চারাগুলো বড় হলে ফুল ও ফল আসে। কিন্তু এক সময় জমির অধিকাংশ বেগুন গাছের কাণ্ডে ও ডগায় বিভিন্ন রকমের পোকার উপস্থিতি দেখা যায় আর কিছু কিছু বেগুনে ছোট কালো ছিদ্র লক্ষ করা যায়। গত বছর এই একই পরিস্থিতিতে তিনি কীটনাশক প্রয়োগ করেছিলেন কিন্তু কোনো উপকার পাননি বরং অর্থের অপচয় হয়েছে। তাই এবার তিনি বিকল্প উপায় খুঁজতে কৃষি কর্মকর্তার সঙ্গে পরামর্শ করেন। ঘ. প্রথম বার সবজি ক্ষেত্রে মনিরা বেগমের গৃহীত পদক্ষেপের ফলাফল মূল্যায়ন কর।'),
  ('class7-agriculture-bn-ch3-p55-q3', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, 3, 'সবুজ সার কী? কীভাবে এ সার তৈরি হয়?'),
  ('class7-agriculture-bn-ch3-p55-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, NULL, 'অ্যাসাইনমেন্ট: গৃহপালিত পশু-পাখির পুষ্টি উপাদানগুলোর উৎস ও কার্যাবলি ছক আকারে পোস্টার পেপারে লিখ এবং দলীয়ভাবে উপস্থাপন কর।'),
  ('class7-agriculture-bn-ch3-p55-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch3', 55, NULL, 'অনুসন্ধানমূলক কাজ: বিভিন্ন প্রকার সারের নমুনা সংগ্রহ করা।'),
  ('class7-agriculture-bn-ch4-p58-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch4', 58, NULL, 'কাজ: শিক্ষার্থীরা এককভাবে কৃষি মৌসুমের বৈশিষ্ট্যগুলো খাতায় লিখে শ্রেণিকক্ষে উপস্থাপন কর।'),
  ('class7-agriculture-bn-ch4-p61-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch4', 61, NULL, 'কাজ: ঋতু অনুযায়ী শস্যের/ফলের বিন্যাস কর। ফসলের/ফলের নাম: পাট, আমন ধান, আলু, তিল, ঢেঁড়স, ফুলকপি, কাঁঠাল, আনারস, পেঁয়াজ, তরমুজ, চালকুমড়া, সরিষা, মুখিকচু, তাল, মসুর। [ছক: রবি | খরিপ-১ | খরিপ-২]'),
  ('class7-agriculture-bn-ch4-p63-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch4', 63, NULL, 'কাজ: শিক্ষার্থীরা চারটি দলে ভাগ হয়ে যাও। এবার তোমাদের দেখানো মিশ্র ফসলের চার্ট থেকে মৌসুম নিরপেক্ষ ফসলের একটি তালিকা তৈরি কর এবং উপস্থাপন কর।'),
  ('class7-agriculture-bn-ch4-p64-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch4', 64, NULL, 'কাজ: শিক্ষার্থীরা চারটি দলে ভাগ হয়ে ফসল উৎপাদনে প্রভাব বিস্তারকারী আবহাওয়া ও জলবায়ুর উপাদানগুলোর একটি তালিকা তৈরি করে শ্রেণিকক্ষে উপস্থাপন কর।'),
  ('class7-agriculture-bn-ch4-p66-t1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch4', 66, NULL, 'কাজ: শিক্ষার্থীরা দুটি দলে ভাগ হয়ে যাও। এক দল অতিবৃষ্টি এবং অপর দল শিলাবৃষ্টির কারণে ফসলের কী কী ক্ষতি হয় তার তালিকা তৈরি করে বোর্ডে উপস্থাপন কর।'),
  ('class7-agriculture-bn-ch4-p66-t2', 'class7-agriculture-bn', 'class7-agriculture-bn-ch4', 66, NULL, 'কাজ-১: শিক্ষক বাংলাদেশের একটি মানচিত্র বোর্ডে ঝুলাবেন। শিক্ষার্থীদের দল গঠন করে বাংলাদেশের কোন জেলায় কোন ফসল ভালো জন্মে সেগুলোর নাম ও জেলার নাম টুকরা কাগজে লিখে মানচিত্রে বসাতে বলবেন। পরিশেষে ফসলসমৃদ্ধ মানচিত্রটি ব্যাখ্যা করবেন।'),
  ('class7-agriculture-bn-ch4-p70-q1', 'class7-agriculture-bn', 'class7-agriculture-bn-ch4', 70, 1, 'বাংলাদেশে শিলাবৃষ্টি কখন হয়-
ক. বৈশাখ ও জ্যৈষ্ঠ
খ. আষাঢ় ও শ্রাবণে
