  ('class7-math-bn-ch4-p67-e12', 'class7-math-bn', 'class7-math-bn-ch4', 67, 12, 'সরল করো : −5 − [−8 − {−4 − (−2 − 3)} + 13]'),
  ('class7-math-bn-ch4-p67-e13', 'class7-math-bn', 'class7-math-bn-ch4', 67, 13, 'সরল করো : 7 − 2[−6 + 3{−5 + 2(4 − 3)}]'),
  ('class7-math-bn-ch4-p67-e14', 'class7-math-bn', 'class7-math-bn-ch4', 67, 14, 'সরল করো : x − {a + (y − b)}'),
  ('class7-math-bn-ch4-p67-e15', 'class7-math-bn', 'class7-math-bn-ch4', 67, 15, 'সরল করো : 3x + (4y − z) − {a − b − (2c − 4a) − 5a}'),
  ('class7-math-bn-ch4-p67-e16', 'class7-math-bn', 'class7-math-bn-ch4', 67, 16, 'সরল করো : −a + [−5b − {−9c + (−3a − 7b + 11c)}]'),
  ('class7-math-bn-ch4-p67-e17', 'class7-math-bn', 'class7-math-bn-ch4', 67, 17, 'সরল করো : −a − [−3b − {−2a − (−a − 4b)}]'),
  ('class7-math-bn-ch4-p67-e18', 'class7-math-bn', 'class7-math-bn-ch4', 67, 18, 'সরল করো : {2a − (3b − 5c)} − [a − {2b − (c − 4a)} − 7c]'),
  ('class7-math-bn-ch4-p67-e19', 'class7-math-bn', 'class7-math-bn-ch4', 67, 19, 'সরল করো : −a + [−6b − {−15c + (−3a − 9b − 13c)}]'),
  ('class7-math-bn-ch4-p67-e20', 'class7-math-bn', 'class7-math-bn-ch4', 67, 20, 'সরল করো : −2x − [−4y − {−6z − (8x − 10y + 12z)}]'),
